effect.shader:
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 c = src.rgb;
float l = gmLum(c);
vec3 cp;
cp.r = clamp(c.r * 1.12 + c.g * 0.06 - c.b * 0.10 + 0.02, 0.0, 1.0);
cp.g = clamp(c.g * 1.02 - c.r * 0.05 + c.b * 0.03, 0.0, 1.0);
cp.b = clamp(c.b * 1.08 + c.r * 0.04 - c.g * 0.02 - 0.04, 0.0, 1.0);
float sh = 1.0 - smoothstep(0.0, 0.5, l);
float hi = smoothstep(0.5, 1.0, l);
cp += vec3(0.02, 0.05, 0.07) * sh * (1.0 - cpWarmth * 0.5) + vec3(0.07, 0.035, 0.0) * hi * (0.5 + cpWarmth * 0.5);
cp -= vec3(0.03, 0.02, 0.05) * sh * cpWarmth * 0.5;
cp = clamp((cp - 0.5) * cpContrast + 0.5, 0.0, 1.0);
float lp = gmLum(cp);
cp = clamp(mix(vec3(lp), cp, cpSat), 0.0, 1.0);
float g = gmHash2(uv * getTexSize(inputImg.size) + fract(acTime) * 53.7);
cp += (g - 0.5) * cpGrain * 0.4;
cp *= 1.0 - cpVignette * 0.85 * smoothstep(0.32, 0.85, length(uv - 0.5));
vec3 col = mix(src.rgb, clamp(cp, 0.0, 1.0), cpStrength * 0.01);
gl_FragColor = vec4(col * src.a, src.a);
}
